fn pager_argument(&self) -> Arg<'static, 'static> {
    let long_help = if self.pager_override.is_empty() {
        "Determine which pager is used. This option will override the              PAGER and BAT_PAGER environment variables. The default pager is 'less'.              To control when the pager is used, see the '--paging' option.              Example: '--pager \"less -RF\"'."
    } else if self.pager_override == "less" || self.pager_override.starts_with("less ") {
        "Determine which pager is used. This option will override the              PAGER and BAT_PAGER environment variables. The default pager is 'less'.              To control when the pager is used, see the '--paging' option.              Example: '--pager \"less -RF\"'."
    } else if self.paging_default == "auto" && self.no_paging_hidden {
        "Determine which pager is used. This option will override the              PAGER and BAT_PAGER environment variables. The default pager is 'less'.              To control when the pager is used, see the '--paging' option.              Example: '--pager \"less -RF\"'."
    } else {
        "Determine which pager is used. This option will override the              PAGER and BAT_PAGER environment variables. The default pager is 'less'.              To control when the pager is used, see the '--paging' option.              Example: '--pager \"less -RF\"'."
    };
    Arg::with_name("pager")
        .long("pager")
        .overrides_with("pager")
        .takes_value(true)
        .value_name("command")
        .hidden_short_help(true)
        .help("Determine which pager to use.")
        .long_help(long_help)

