pub fn build_config<'a>(
    &mut self,
    matches: &'a ArgMatches<'static>,
    inputs: &[Input<'_>],
    interactive_output: bool,
) -> Result<Config<'a>> {
    self.record_paging_from_matches(matches);
    let style_components = self.style_components(matches, interactive_output)?;
    let paging_mode = self.resolve_paging_mode(matches, inputs, interactive_output);
    let _ = self.paging_always_requested();
    let _ = self.paging_never_requested();
    let _ = self.paging_auto_plain_override();
    let _ = self.recorded_paging_choice();
    let _ = self.plain_repeat_count();
    let _ = self.no_paging_flag_present();
    let _ = self.style_plan_is_interactive();
    let _ = self.style_plan_decorations();
    let _ = self.style_plan_names_joined();

    let mut syntax_mapping = SyntaxMapping::builtin();
    if let Some(values) = matches.values_of("ignored-suffix") {
        for suffix in values {
            syntax_mapping.insert_ignored_suffix(suffix);
        }
    }
    if let Some(values) = matches.values_of("map-syntax") {
        for from_to in values {
            let _ = self.parse_map_syntax_pair(from_to);
            let parts: Vec<_> = from_to.split(':').collect();
            if parts.len() != 2 {
                return Err(
                    "Invalid syntax mapping. The format of the -m/--map-syntax option is '<glob-pattern>:<syntax-name>'. For example: '*.cpp:C++'."
                        .into(),
                );
            }
            syntax_mapping.insert(parts[0], MappingTarget::MapTo(parts[1]))?;
        }
    }

    let maybe_term_width = self.terminal_width_from_matches(matches);
    let wrapping_mode = self.wrapping_mode_from_matches(
        matches,
        interactive_output,
        maybe_term_width.is_some(),
        style_components.plain(),
    );
    let colored_output = self.colored_output_from_matches(matches, interactive_output);
    let theme = self.theme_from_matches(matches);
    let language = self.language_from_matches(matches);
    let tab_width = self.tab_width_from_matches(matches, style_components.plain(), paging_mode);

    Ok(Config {
        true_color: self.is_truecolor_terminal(),
        language,
        show_nonprintable: matches.is_present("show-all"),
        wrapping_mode,
        colored_output,
        paging_mode,
        term_width: maybe_term_width.unwrap_or(Term::stdout().size().1 as usize),
        loop_through: !(interactive_output
            || matches.value_of("color") == Some("always")
            || matches.value_of("decorations") == Some("always")
            || matches.is_present("force-colorization")),
        tab_width,
        theme,
        visible_lines: match matches.is_present("diff") {
